/// Entity with a position and orientation in 3D space.
struct Spatial {
    float position_x;
    float position_y;
    float position_z;
    /// Direction entity faces in radians.
    std::optional<float> facing_angle = std::nullopt;
};


/// Entity made of a physical material.
struct HasMaterial {
    std::optional<MaterialType> material_type = std::nullopt;
    /// Density in kg/m3.
    std::optional<float> material_density = std::nullopt;
    /// Coulomb friction coefficient.
    std::optional<float> material_friction = std::nullopt;
    /// Tensile strength in Pa.
    std::optional<float> material_strength = std::nullopt;
};


/// Entity that can take damage and die.
struct HasHealth {
    float health;
    float max_health;
};


/// Entity that emits light and can be seen from a distance.
struct EmitsLight {
    /// Light intensity (lux).
    std::optional<float> emission_strength = std::nullopt;
    /// Maximum light reach distance.
    std::optional<float> emission_radius = std::nullopt;
};


/// Physical performance attributes of a body component or agent.
struct HasPhysicalCapability {
    /// Force production capacity in Newtons. 0 = non-functional.
    std::optional<float> part_strength = std::nullopt;
    /// Maximum force capacity ceiling in Newtons. Degrades with permanent injury.
    std::optional<float> part_max_strength = std::nullopt;
    /// Range of motion ratio. 0.0 = locked, 1.0 = full ROM.
    std::optional<float> part_flexibility = std::nullopt;
    /// Neural response speed for this part in milliseconds. Lower = faster.
    std::optional<float> part_responsiveness = std::nullopt;
    /// Action cycles before fatigue. Drains with use, recovers with rest.
    std::optional<float> part_endurance = std::nullopt;
};


/// Tissue-level health tracking for body parts. Different damage types affect different tissues.
struct HasTissue {
    /// Muscle tissue integrity 0-100. Affects power production. Damaged by CUT, CRUSH.
    std::optional<float> muscle_health = std::nullopt;
    /// Nerve tissue integrity 0-100. Affects control/speed. Damaged by PIERCE, CRUSH.
    std::optional<float> nerve_health = std::nullopt;
    /// Tendon integrity 0-100. At 0 = limb unusable. Damaged by CUT.
    std::optional<float> tendon_health = std::nullopt;
    /// Bone integrity 0-100. At 0 = fracture. Damaged by CRUSH.
    std::optional<float> bone_health = std::nullopt;
};


/// Entity that produces a detectable scent.
struct HasOdor {
    std::optional<OdorType> odor_type = std::nullopt;
};


/// Carries who owns this body's position. Every body in the world has it, because immobility is always a choice, never an accident of being still.
struct HasSolverAuthority {
    /// Who owns this body's position. Omit for DYNAMIC. Set KINEMATIC to make something genuinely immovable - terrain, a floor, a world. Never try to hold a structure up by leaving it still; stillness is an optimisation the physics undoes on contact.
    std::optional<SolverAuthority> solver_authority = std::nullopt;
};


/// Can be cemented to other bodies through a BONDED_TO relation. bond_strength is how much load the join carries before it gives.
struct Bondable {
    /// Load a BONDED_TO join carries before it gives, in newtons per metre. Around 90000 behaves as rigid cement; small values give under their own weight.
    std::optional<float> bond_strength = std::nullopt;
};


/// Entity that can be damaged or destroyed.
struct Destructible {
    /// Damage required to trigger destruction.
    std::optional<float> damage_threshold = std::nullopt;
    std::optional<EntityModification> modification_state = std::nullopt;
};


/// Entity that grows over time via procedural generation.
struct Growable {
    std::optional<int32_t> growth_iteration = std::nullopt;
    std::optional<bool> is_mature = std::nullopt;
    std::optional<std::string> species = std::nullopt;
};


/// Anything with a stable, globally unique identity. Aligned with BFO Independent Continuant: exists on its own, bears qualities, participates in processes.
struct Identifiable {
    /// Globally unique identifier.
    std::string id;
    /// Human-readable name.
    std::optional<std::string> name = std::nullopt;
};


/// Timestamps for creation and last modification. Follows PROV-O temporal patterns.
struct Temporal {
    /// When this was created.
    std::optional<std::string> created_at = std::nullopt;
    /// When this was last modified.
    std::optional<std::string> updated_at = std::nullopt;
};


/// Human-readable description and metadata.
struct Describable {
    /// Free-text description.
    std::optional<std::string> description = std::nullopt;
    /// Arbitrary classification tags.
    std::vector<std::string> tags = {};
};


/// Entity with a lifecycle status.
struct Statusable {
    /// Lifecycle status.
    std::optional<EntityStatus> status = std::nullopt;
};


/// Capability of acting, deciding, or bearing responsibility. Aligned with PROV:Agent and BDI model. Agency is a trait, not a taxonomic position: an entity CAN act, it is not defined by acting. Apply this mixin to any entity class that needs volitional behavior.
struct Agent {
    /// Classification of the agent. Domain projects should constrain this to an enum.
    std::optional<std::string> agent_type = std::nullopt;
};


/// Root class for all identifiable, enduring things. Aligned with BFO:Independent Continuant. Every domain object that persists through time and needs identity extends this.
struct Entity : public Identifiable, public Temporal, public Describable {
};


